def overview_page():
    return '<html><head><title>状态概览 · WhatsApp AI 管理面板</title><style>' + SHARED_CSS + MONITOR_CSS + '''</style></head><body>
<div class="monitoring-page" id="overviewPage"><header class="page-heading"><div><h1>状态概览</h1><p>连接、自动回复与待处理事项，一处查看。</p></div><div class="page-heading-tools"><label class="control-label" for="overviewScope">统计范围<select id="overviewScope"><option value="all">全部会话</option></select></label><button class="primary" id="refreshOverview" type="button">刷新状态</button></div></header>
<div class="monitor-notice" id="overviewNotice" role="status" aria-live="polite">正在读取状态…</div>
<div class="overview-stats"><button class="stat-card" type="button" data-state-filter="all" aria-pressed="true"><span>会话总数</span><strong data-overview-count="total">—</strong></button><button class="stat-card" type="button" data-state-filter="connected" aria-pressed="false"><span>已连接</span><strong data-overview-count="connected">—</strong></button><button class="stat-card" type="button" data-state-filter="scan_qr" aria-pressed="false"><span>待扫码</span><strong data-overview-count="scan_qr">—</strong></button><button class="stat-card" type="button" data-state-filter="failed" aria-pressed="false"><span>连接失败</span><strong data-overview-count="failed">—</strong></button></div>
<section class="monitor-card"><h2>服务状态</h2><div class="service-grid"><div><div class="service-summary"><strong>WAHA</strong><span class="state-chip" id="overviewWaha">检查中</span></div><p class="service-detail" id="overviewWahaDetail">正在读取健康接口与版本…</p></div><div><div class="service-summary"><strong>数据存储</strong><span class="state-chip" id="overviewDatabase">检查中</span></div><p class="service-detail" id="overviewCheckedAt">最后成功采样：—</p></div></div></section>
<section class="monitor-card"><h2>会话状态</h2><p class="section-note">AI 已配置表示设置齐全；连接是否可用需结合实际调用结果判断。</p><table class="status-table"><thead><tr><th>会话</th><th>连接状态</th><th>自动回复</th><th>AI 设置</th><th>检查时间</th><th>操作</th></tr></thead><tbody id="overviewSessions"></tbody></table><p class="section-note" id="overviewConfigSummary"></p></section>
<section class="monitor-card"><h2>待处理事项</h2><p class="section-note">以下为当前任务状态；待确认的发送结果请先核对聊天记录。</p><div class="automation-grid" id="overviewAutomation"></div><div class="card-actions"><a id="overviewTaskLogs" href="/logs">查看任务记录</a><span class="section-note" id="overviewOverdue"></span></div></section>
<section class="monitor-card"><h2>最近异常 <span class="state-chip" id="overviewErrorCount">—</span></h2><p class="section-note">最近 24 小时面板已记录的警告与错误。</p><div class="event-list" id="overviewErrors"></div><div class="card-actions"><a id="overviewAllLogs" href="/logs">查看全部日志</a></div></section>
</div></body></html>'''
